/** Seeded random numbers in 0..1 (mulberry32). */
export declare function mulberry32(seed: number): () => number;
export declare const GLSL_HASH = "\nfloat hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }\nfloat hash21(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); } // not-colour: hash lanes\nvec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); } // not-colour: hash lanes\n";
/** Simplex noise in 2D: snoise(p) is about -1..1 and smooth. */
export declare const GLSL_NOISE = "\nvec3 _mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }\nvec2 _mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }\nvec3 _permute(vec3 x) { return _mod289(((x * 34.0) + 1.0) * x); }\nfloat snoise(vec2 v) {\n  const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);\n  vec2 i = floor(v + dot(v, C.yy));\n  vec2 x0 = v - i + dot(i, C.xx);\n  vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);\n  vec4 x12 = x0.xyxy + C.xxzz;\n  x12.xy -= i1;\n  i = _mod289(i);\n  vec3 p = _permute(_permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0)); // not-colour: lattice corners\n  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0); // not-colour: corner falloff\n  m = m * m; m = m * m;\n  vec3 x = 2.0 * fract(p * C.www) - 1.0;\n  vec3 h = abs(x) - 0.5;\n  vec3 ox = floor(x + 0.5);\n  vec3 a0 = x - ox;\n  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);\n  vec3 g;\n  g.x = a0.x * x0.x + h.x * x0.y;\n  g.yz = a0.yz * x12.xz + h.yz * x12.yw;\n  return 130.0 * dot(m, g);\n}\n";
/** `octaves` of snoise (needs GLSL_NOISE). fbm(p, n) is about -1..1. */
export declare const GLSL_FBM = "\nfloat fbm(vec2 p, int octaves) {\n  float s = 0.0, a = 0.5, n = 0.0;\n  mat2 r = mat2(0.8, -0.6, 0.6, 0.8);\n  for (int i = 0; i < 8; i++) { if (i >= octaves) break; s += a * snoise(p); n += a; p = r * p * 2.02 + 7.3; a *= 0.5; }\n  return s / n;\n}\n";
